ontology:
# 引用原 JOIN 规则，指标计算口径仍由现有提示词维护。
entities:
  plan: {table: FIMS.TB_DYN_FLIGHT, alias: f1}
  actual: {table: ACDM.TB_DYN_FLIGHT, alias: f2, parent: plan, join_rule: BASE_FLIGHT}
  terminal: {table: FIMS.TBH_FIMS_DYN_CALC_TOTAL, alias: t, parent: plan, join_rule: TERMINAL_CD}
  site: {table: FIMS.TB_CRAFT_SITE, alias: s, parent: actual, join_rule: CRAFT_SITE_CD}
  airline: {table: FIMS.TB_AIRLINE, alias: air, parent: actual, join_rule: AIRLINE_TWO_CHAR_CD}
  agency: {table: FIMS.TB_AGENCY, alias: agency, parent: actual, join_rule: AGENCY}
  task: {table: FIMS.TB_FLIGHT_TASK, alias: ft, parent: plan, join_rule: FLIGHT_TASK_CD}
  craft_type: {table: FIMS.TB_CRAFT_TYPE, alias: ct, parent: actual, join_rule: CRAFT_TYPE_ICAO_CD}
  departure_airport: {table: FIMS.TB_AIRPORT, alias: dep, parent: actual, join_rule: TAKEOFF_AIRPORT_IATA}
  arrival_airport: {table: FIMS.TB_AIRPORT, alias: arr, parent: actual, join_rule: ARRIVAL_AIRPORT_IATA}
  abnormal_reason: {table: FIMS.TB_ABNORMAL_REASON, alias: r, parent: actual, join_rule: DELAY_REASON}
fields:
  PLAN_TIME: {entity: plan, column: PLAN_TIME}
  AIRLINE_TWO_CHAR_CD: {entity: plan, column: AIRLINE_TWO_CHAR_CD}
  ATTRIBUTE: {entity: plan, column: '"ATTRIBUTE"', values: {国际: '2401', 地区: '2402', 国内: '2403', 混合: '2404'}}
  IS_OFF_IN: {entity: plan, column: IS_OFF_IN, values: {进港: A, 出港: D}}
  FLIGHT_TASK_CD: {entity: plan, column: FLIGHT_TASK_CD}
  CRAFT_NO: {entity: plan, column: CRAFT_NO}
  AGENCY: {entity: actual, column: AGENCY, values: {机场: '210', 东航: '211', 国航: '212', 南航: '215'}}
  FLIGHT_NO: {entity: actual, column: FLIGHT_NO}
  GATE_CD: {entity: actual, column: GATE_CD}
  CRAFT_SITE_CD: {entity: actual, column: CRAFT_SITE_CD}
  CRAFT_TYPE_ICAO_CD: {entity: actual, column: CRAFT_TYPE_ICAO_CD}
  TAKEOFF_AIRPORT_IATA: {entity: actual, column: TAKEOFF_AIRPORT_IATA}
  ARRIVAL_AIRPORT_IATA: {entity: actual, column: ARRIVAL_AIRPORT_IATA}
  REAL_TAKEOFF_TIME: {entity: actual, column: REAL_TAKEOFF_TIME}
  REAL_LANDIN_TIME: {entity: actual, column: REAL_LANDIN_TIME}
  TERMINAL_CD: {entity: terminal, column: TERMINAL_CD}
  CRAFT_SITE_IS_REMOTE: {entity: site, column: IS_REMOTE, values: {靠桥: N, 远机位: Y}}
  AIRLINE_CHINESE_NAME: {entity: airline, column: CHINESE_NAME}
  AGENCY_CHINESE_NAME: {entity: agency, column: CHINESE_NAME}
  FLIGHT_TASK_CHINESE_NAME: {entity: task, column: CHINESE_NAME}
  CRAFT_TYPE_CHINESE_NAME: {entity: craft_type, column: CHINESE_NAME}
  TAKEOFF_AIRPORT_CHINESE_NAME: {entity: departure_airport, column: CHINESE_NAME}
  ARRIVAL_AIRPORT_CHINESE_NAME: {entity: arrival_airport, column: CHINESE_NAME}
  ABNORMAL_REASON_CHINESE_NAME: {entity: abnormal_reason, column: CHINESE_NAME}
metric_dependencies:
  靠桥率: [CRAFT_SITE_IS_REMOTE]
  实际使用廊桥的航班数: [CRAFT_SITE_IS_REMOTE]
  外保障航班: [CRAFT_SITE_IS_REMOTE]
rules:
  - EXEC_DATE 是日期槽位，不是主表字段；计划指标按 PLAN_TIME，实际起降指标按方向使用 REAL_TAKEOFF_TIME 或 REAL_LANDIN_TIME。
  - 编码筛选直接使用字段所属表，仅查询名称或关联属性时才关联维表；航空公司与航班代理不得互相替代。
  - 关联表可能有多条记录，必须保持指标的航班去重口径，不得把 JOIN 后行数直接当架次。
  - 只加入本次筛选、取列、分组和指标计算所需的关联；子查询外层通过输出别名取列。
  - 用户原文优先纠正槽位；指标计算步骤优先于 SQL 示例的冲突口径，示例仅为参考。
  - Oracle 小时截断使用 TRUNC(time_column, 'HH24')，时间显示使用 TO_CHAR(time_column, 'HH24:MI')，不要使用无效格式 HH24:00。
  - 无实际航班记录时不得把人工时间桶产生的零计数称为高峰；分母为零的比率返回无数据，不得解释为零百分比。
  - 起降高峰时段必须先为每条去重航班构造唯一 event_time：出港 D 使用 REAL_TAKEOFF_TIME，进港 A 使用 REAL_LANDIN_TIME；仅按 TRUNC(event_time, 'HH24') 分组，统计同一小时内进港加出港总架次。禁止同时按起飞和落地两个时间分组，也禁止将所有航班都按起飞时间分组。
